});

pm.test("พบเหตุผลที่ไม่ผ่านคุณสมบัติ", function () {
    const reasons = pm.response.json().reasons;

    pm.expect(reasons).to.include("GPA ต้องไม่ต่ำกว่า 2.75");
    pm.expect(reasons).to.include("คพ.100 ต้องได้เกรด C+ ขึ้นไป");
    pm.expect(reasons).to.include(
        "คพ.180 ต้องกำลังศึกษา หรือเคยศึกษาแล้ว"
    );
    pm.expect(reasons).to.include(
        "ต้องยืนยันเงื่อนไขให้ครบทั้ง 3 ข้อ"
    );
});

